10	/**
11	 * Process-wide signed-URL cache.
12	 *
13	 * `createSignedUrls` returns a NEW token every call, so re-signing the same file
14	 * yields a different URL — which the browser treats as a different image and
15	 * re-downloads. Measured on the generator: switching occasion produced 3 of 3
16	 * identical files and 0 of 3 identical URLs.
17	 *
18	 * Caching is safe because a signed URL is a capability for one path, and the
19	 * caller has already had to obtain that path through RLS to ask for it. The
20	 * cache grants nothing a caller could not mint for itself a line later.
21	 */
22	const cache: UrlCache = new Map();
23	
24	export async function signItemImages(paths: string[], expiresIn = 3600) {
25	  const map = new Map<string, string>();
26	  if (paths.length === 0) return map;
27	
28	  const now = Date.now();
29	  const { fresh, stale } = partition(paths, cache, now, REFRESH_MARGIN_MS);
30	  for (const [path, url] of fresh) map.set(path, url);
31	  if (stale.length === 0) return map;
32	
33	  const supabase = await createClient();
34	  const { data } = await supabase.storage.from("wardrobe").createSignedUrls(stale, expiresIn);
35	
36	  const minted = new Map<string, string>();
37	  data?.forEach((d) => {
38	    if (d.path && d.signedUrl) minted.set(d.path, d.signedUrl);
39	  });
40	
41	  store(cache, minted, now, Math.min(TTL_MS, expiresIn * 1000));
42	  for (const [path, url] of minted) map.set(path, url);
43	  return map;
44	}
